    { grade: 7, lesson: 11, type: "essay", q: "دو نمونه از نمودارهای آب و هوایی را نام ببرید؟", key: "نمودار ستونی (برای بارش) و نمودار خطی (برای دما)." },
    { grade: 7, lesson: 11, type: "jakhali", q: "میزان دمای هوای یک ناحیه را با نمودار ...... و با رنگ ...... نشان می دهند.", answer: ["خطی", "قرمز"] },
    { grade: 7, lesson: 11, type: "jakhali", q: "میزان بارش هوای یک ناحیه را با نمودار ...... و با رنگ ...... نشان می دهند.", answer: ["ستونی", "آبی"] },
    { grade: 7, lesson: 11, type: "essay", q: "به طور کلی ایران دارای چند ناحیه آب و هوایی است؟ نام ببرید.", key: "چهار ناحیه: معتدل و مرطوب خزری، معتدل و نیمه خشک کوهستانی، گرم و خشک داخلی، گرم و شرجی سواحل جنوب." },
    { grade: 7, lesson: 11, type: "essay", q: "ناحیه معتدل و مرطوب خزری دارای چه ویژگی هایی است؟", key: "بارش زیاد، هوای مرطوب، تابستان های معتدل، زمستان های ملایم." },
    { grade: 7, lesson: 11, type: "essay", q: "ناحیه معتدل و نیمه خشک کوهستانی چه ویژگی هایی دارد؟", key: "زمستان های سرد و طولانی، تابستان های معتدل، بارش متوسط." },
    { grade: 7, lesson: 11, type: "essay", q: "ناحیه گرم و خشک داخلی دارای چه ویژگی هایی است؟", key: "بارش کم، اختلاف دمای زیاد بین روز و شب، تابستان های بسیار گرم." },
    { grade: 7, lesson: 11, type: "essay", q: "ناحیه گرم و شرجی سواحل جنوب دارای چه ویژگی هایی است؟", key: "تابستان های بسیار گرم و مرطوب، زمستان های معتدل، بارش کم." },
    { grade: 7, lesson: 12, type: "essay", q: "کدام عامل موجب تنوع زیاد در گونه های گیاهی و جانوری ایران شده است؟", key: "تنوع آب و هوایی و شرایط جغرافیایی." },
    { grade: 7, lesson: 12, type: "essay", q: "کدام گونه های گیاهی و جانوری مخصوص سرزمین ایران است؟", key: "گونه های بومی مانند یوزپلنگ آسیایی، گوزن زرد ایرانی." },
    { grade: 7, lesson: 12, type: "essay", q: "چرا زیستگاه ها تخریب می شوند؟", key: "به دلیل فعالیت های انسانی مانند شهرسازی، جاده سازی، آلودگی." },
    { grade: 7, lesson: 12, type: "essay", q: "مهمترین عامل از بین رفتن یا در معرض خطر قرار گرفتن برخی از گونه های گیاهی و جانوری چیست؟", key: "تخریب زیستگاه ها توسط انسان." },
    { grade: 7, lesson: 12, type: "essay", q: "انسان در بهره برداری از طبیعت و رفع نیازهای خود چگونه باید عمل کند؟", key: "باید به گونه ای عمل کند که به طبیعت آسیب نزند و از منابع به صورت پایدار استفاده کند." },
    { grade: 7, lesson: 12, type: "essay", q: "نابود شدن درختان جنگلی در یک ناحیه چه نتایجی دارد؟", key: "فرسایش خاک، سیل، کاهش اکسیژن، از بین رفتن حیات وحش." },
    { grade: 7, lesson: 12, type: "essay", q: "شکار بیش از حد و صید بی رویه جانوران چه پیامدی به دنبال دارد؟", key: "انقراض گونه ها و به هم خوردن تعادل اکوسیستم." },
    { grade: 7, lesson: 12, type: "jakhali", q: "یکی از چیزهایی که حیات زیستگاه ها را تهدید می کند، ...... است.", answer: ["آلودگی", "تخریب", "شکار بی رویه"] },
    { grade: 7, lesson: 12, type: "essay", q: "مهمترین دلایل حفاظت از زیستگاه ها را بنویسید؟", key: "حفظ تنوع زیستی، حفظ منابع طبیعی برای آیندگان، حفظ تعادل اکوسیستم." },
    { grade: 7, lesson: 12, type: "essay", q: "هشتم آبان ماه به چه روزی نام گذاری شده است؟", key: "روز نوجوان و دانش آموز." },
    { grade: 7, lesson: 12, type: "essay", q: "مهمترین وظیفه سازمان حفاظت از محیط زیست چیست؟", key: "حفاظت از محیط زیست، جلوگیری از آلودگی و تخریب آن." },
    { grade: 7, lesson: 12, type: "jakhali", q: "یکی از مشاغل مهم در سازمان حفاظت از محیط زیست ...... است.", answer: ["محیط بان", "محیط بانی"] },
    { grade: 7, lesson: 12, type: "essay", q: "وظایف محیط بانان را نام ببرید.", key: "گشت زنی، جلوگیری از شکار غیرقانونی، حفاظت از حیات وحش و گیاهان." },
    { grade: 7, lesson: 12, type: "essay", q: "محیط بان ها چه مواردی را به سازمان حفاظت از محیط زیست گزارش می کنند؟", key: "تخریب زیستگاه ها، شکار غیرقانونی، آتش سوزی، آلودگی." },
    { grade: 7, lesson: 12, type: "truefalse", q: "حفاظت از محیط زیست فقط وظیفه سازمان حفاظت از محیط زیست نیست، بلکه وظیفه همه ما است.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 12, type: "essay", q: "برخی از کارهایی که شما می توانید برای حفاظت از محیط زیست انجام دهید را بنویسید.", key: "صرفه جویی در آب و برق، تفکیک زباله، کاشتن درخت." },
    { grade: 7, lesson: 12, type: "essay", q: "منطقه حفاظت شده به چه منطقه ای گفته می شود؟", key: "مناطقی که به دلیل داشتن گونه های نادر گیاهی و جانوری، تحت حفاظت قرار می گیرند." },
    { grade: 7, lesson: 12, type: "essay", q: "سه مورد از مناطق حفاظت شده ایران را نام ببرید؟", key: "پارک ملی گلستان، منطقه حفاظت شده ارسباران، پارک ملی کویر." },
    { grade: 7, lesson: 12, type: "essay", q: "در مناطق حفاظت شده انجام چه کارهایی ممنوع است؟", key: "شکار، صید، تخریب، چرای دام، ساخت و ساز." },
    { grade: 7, lesson: 12, type: "essay", q: "اصل ۵۰ قانون اساسی چه چیزی را مطرح می کند؟", key: "حفاظت از محیط زیست یک وظیفه عمومی است و فعالیت هایی که باعث تخریب آن شود ممنوع است." },
    { grade: 7, lesson: 13, type: "essay", q: "جمعیت ایران چند میلیون نفر است؟", key: "حدود ۸۵ میلیون نفر." },
    { grade: 7, lesson: 13, type: "testi", q: "ایران در بین کشورهای همسایه از نظر جمعیت در چه رتبه ای قرار دارد؟", options: ["اول", "دوم", "سوم", "چهارم"], answer: [1] },
    { grade: 7, lesson: 13, type: "essay", q: "جمعیت چگونه افزایش می یابد؟", key: "وقتی موالید (تولدها) بیشتر از مرگ و میر باشد." },
    { grade: 7, lesson: 13, type: "essay", q: "در چه صورت جمعیت کاهش می یابد؟", key: "وقتی مرگ و میر بیشتر از موالید باشد." },
    { grade: 7, lesson: 13, type: "essay", q: "رشد منفی جمعیت چیست؟", key: "کاهش جمعیت به دلیل کمتر شدن تولدها نسبت به مرگ و میر." },
    { grade: 7, lesson: 13, type: "truefalse", q: "کشورهایی که تشکیل خانواده در آنها کمتر صورت می گیرد، دارای رشد منفی در جمعیت نمی باشند.", options: ["درست", "غلط"], answer: [1] },
    { grade: 7, lesson: 13, type: "essay", q: "وقتی رشد جمعیت منفی می شود کشورها با چه مشکلاتی روبرو می شوند؟", key: "پیری جمعیت، کاهش نیروی کار، مشکلات اقتصادی." },
    { grade: 7, lesson: 13, type: "truefalse", q: "جمهوری اسلامی ایران در بین کشورهای همسایه خود، کشوری پر جمعیت است.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 13, type: "essay", q: "جمعیت را به چند گروه سنی مختلف تقسیم می کنند؟ نام ببرید.", key: "سه گروه: کمتر از ۱۵ سال، ۱۵ تا ۶۴ سال، ۶۵ سال به بالا." },
    { grade: 7, lesson: 13, type: "jakhali", q: "در کشور ما ...... مسئولیت سرشماری جمعیت را بر عهده دارد.", answer: ["مرکز آمار ایران"] },
    { grade: 7, lesson: 13, type: "essay", q: "وظیفه مرکز آمار ایران چیست؟", key: "جمع آوری، تحلیل و انتشار آمار جمعیتی و اقتصادی." },
    { grade: 7, lesson: 13, type: "essay", q: "تراکم جمعیت چیست؟", key: "تعداد افرادی که در یک کیلومتر مربع زندگی می کنند." },
    { grade: 7, lesson: 13, type: "essay", q: "تراکم جمعیت یک منطقه را چگونه محاسبه می کنند؟", key: "تقسیم جمعیت بر مساحت." },
    { grade: 7, lesson: 13, type: "essay", q: "فرمول تراکم جمعیت را بنویسید.", key: "تراکم جمعیت = جمعیت ÷ مساحت (کیلومتر مربع)" },
    { grade: 7, lesson: 13, type: "essay", q: "تراکم جمعیت کشورمان در سال ۱۴۰۰ چند نفر در کیلومتر مربع بود؟ این تراکم چگونه محاسبه شده است؟", key: "حدود ۵۰ نفر در کیلومتر مربع. با تقسیم جمعیت کشور بر مساحت آن." },
    { grade: 7, lesson: 13, type: "essay", q: "چرا در بخشی از نواحی داخلی ایران جمعیت بسیار کمی زندگی می کنند؟", key: "به دلیل شرایط سخت آب و هوایی، کم آبی و بیابانی بودن." },
    { grade: 7, lesson: 13, type: "essay", q: "کدام مناطق ایران خالی از جمعیت است؟", key: "کویر لوت، دشت کویر، ارتفاعات بسیار بلند." },
    { grade: 7, lesson: 13, type: "essay", q: "تراکم جمعیت در نواحی داخلی ایران چگونه است؟", key: "بسیار کم و پراکنده." },
    { grade: 7, lesson: 13, type: "testi", q: "پرجمعیت ترین و پرتراکم ترین ناحیه کشورمان کجاست؟", options: ["ناحیه خوزستان", "منطقه شهری تهران", "کناره های دریای خزر", "کوهپایه های زاگرس"], answer: [1] },
    { grade: 7, lesson: 13, type: "essay", q: "چرا منطقه شهری تهران، پرجمعیت ترین و پرتراکم ترین ناحیه کشور است؟", key: "به دلیل پایتخت بودن، وجود فرصت های شغلی، امکانات آموزشی و بهداشتی." },
    { grade: 7, lesson: 13, type: "essay", q: "جمعیت زیاد در تهران و شهرهای پر جمعیت چه مشکلاتی را به وجود آورده است؟", key: "آلودگی هوا، ترافیک، کمبود مسکن، بیکاری." },
    { grade: 7, lesson: 13, type: "essay", q: "دومین ناحیه پرتراکم در کشور ما کجاست؟", key: "جلگه های کناره دریای خزر." },
    { grade: 7, lesson: 13, type: "essay", q: "علت پر تراکم بودن جمعیت در جلگه های کناره دریای خزر چیست؟", key: "خاک حاصلخیز، آب فراوان، آب و هوای مناسب." },
    { grade: 7, lesson: 13, type: "essay", q: "علت جذب جمعیت در ناحیه خوزستان چیست؟", key: "وجود رودخانه های پرآب، زمین های کشاورزی، صنایع (نفت)." },
    { grade: 7, lesson: 13, type: "essay", q: "به چه دلیل کوهپایه های البرز و زاگرس و دشت ها جمعیت زیادی را به خود جذب کرده است؟", key: "وجود آب، خاک مناسب، آب و هوای معتدل، امنیت." },
    { grade: 7, lesson: 13, type: "essay", q: "متن صفحه ۷۸ را بخوانید، سپس روی کاغذ جدولی با دو ستون رسم کنید در یک ستون نام ناحیه و در ستون دیگر عوامل مؤثر در پراکندگی جمعیت آن ناحیه را بنویسید.", key: "ناحیه خزر (کشاورزی، آب و هوا)، تهران (صنعت، خدمات)، خوزستان (نفت، کشاورزی)." },
    { grade: 7, lesson: 14, type: "truefalse", q: "آب و خاک از منابع نامحدود هستند.", options: ["درست", "غلط"], answer: [1] },
    { grade: 7, lesson: 14, type: "essay", q: "آب مورد نیاز انسان چگونه تأمین می شود؟", key: "از طریق بارش، رودها، آب های زیرزمینی." },
    { grade: 7, lesson: 14, type: "testi", q: "کدام یک از موارد زیر جزء آب های زیرزمینی نیست؟", options: ["چاه", "رودها", "چشمه", "قنات"], answer: [1] },
    { grade: 7, lesson: 14, type: "essay", q: "با توجه به تصویر صفحه ۷۹ چرخه ی آب در طبیعت را توضیح دهید.", key: "تبخیر آب از دریاها، تشکیل ابر، بارش، جاری شدن در رودها و نفوذ در زمین." },
    { grade: 7, lesson: 14, type: "truefalse", q: "کشور ما دارای منابع محدود است.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 14, type: "jakhali", q: "یکی از منابع مهم تأمین آب شهرنشینان و روستاییان، ...... هستند.", answer: ["رودها", "آب های زیرزمینی"] },
    { grade: 7, lesson: 14, type: "jakhali", q: "اغلب رودهای دائمی و پر آب ایران از کوه های ...... و ...... سرچشمه می گیرند.", answer: ["البرز", "زاگرس"] },
    { grade: 7, lesson: 14, type: "essay", q: "چرا رودهای پر آب ایران قابل کشتیرانی نیستند؟", key: "به دلیل شیب زیاد، عمق کم و وجود آبشارها." },
    { grade: 7, lesson: 14, type: "testi", q: "کدام رود ایران قابل کشتیرانی است؟", options: ["زرینه رود", "سیمینه رود", "زاینده رود", "کارون"], answer: [3] },
    { grade: 7, lesson: 14, type: "essay", q: "رودهای ایران از نظر جهت جریان آب به چند حوضه آبریز تقسیم می شوند؟ نام ببرید.", key: "سه حوضه: دریای خزر، خلیج فارس و دریای عمان، داخلی." },
    { grade: 7, lesson: 14, type: "testi", q: "رودهایی که از کوه های البرز و ارتفاعات شمالی کشور سرچشمه می گیرند به کدام حوضه آبریز می ریزند؟", options: ["خلیج فارس", "دریای خزر", "دریای عمان", "داخلی"], answer: [1] },
    { grade: 7, lesson: 14, type: "testi", q: "رودهایی که از کوه های زاگرس یا کوه های پراکنده داخلی سرچشمه می گیرند به کجا می ریزند؟", options: ["خلیج فارس", "دریای خزر", "خلیج فارس و دریای عمان", "داخلی"], answer: [2] },
    { grade: 7, lesson: 14, type: "testi", q: "رودهای موقتی یا فصلی در کدام حوضه آبریز ایران وجود دارد؟", options: ["خلیج فارس", "دریای خزر", "دریای عمان", "داخلی"], answer: [3] },
    { grade: 7, lesson: 14, type: "essay", q: "روده‌های حوضه آبریز داخلی به کجا می‌ریزند؟", key: "به دریاچه ها، باتلاق ها یا در زمین فرو می روند." },
    { grade: 7, lesson: 14, type: "testi", q: "میزان مجاز مصرف آب برای یک نفر در شبانه روز چقدر است؟", options: ["۱۰۰ لیتر", "۱۵۰ لیتر", "۲۰۰ لیتر", "۲۵۰ لیتر"], answer: [1] },
    { grade: 7, lesson: 14, type: "essay", q: "میزان متوسط مصرف آب در ایران برای یک فرد چقدر است؟", key: "بیشتر از ۲۰۰ لیتر." },
    { grade: 7, lesson: 14, type: "essay", q: "برای مصرف درست آب چه نکاتی را باید رعایت کنیم؟", key: "بستن شیر آب، تعمیر لوله های آب، استفاده از دوش به جای وان." },
    { grade: 7, lesson: 14, type: "essay", q: "چه کمکی ما برای آلوده نکردن آب می توانیم بکنیم؟", key: "نریختن زباله در آب، استفاده نکردن از مواد شیمیایی در آب." },
    { grade: 7, lesson: 14, type: "jakhali", q: "خاک یک منبع مهم تأمین ...... است.", answer: ["غذا", "کشاورزی"] },
    { grade: 7, lesson: 14, type: "essay", q: "چند کاربرد خاک را در زندگی انسان نام ببرید.", key: "کشاورزی، ساخت و ساز، صنایع سفالگری." },
    { grade: 7, lesson: 14, type: "essay", q: "خاک چگونه تشکیل می شود؟", key: "با خرد شدن سنگ ها در اثر عوامل طبیعی مانند آب، باد و دما در طول سال ها." },
    { grade: 7, lesson: 14, type: "essay", q: "خاک مناطق جلگه ای ایران را با خاک مناطق مرکزی مقایسه کنید.", key: "خاک جلگه ها حاصلخیزتر است و مواد آلی بیشتری دارد، خاک مرکزی شور و نامناسب است." },
    { grade: 7, lesson: 14, type: "essay", q: "در کدام مناطق کشور ما خاک حاصلخیز وجود دارد؟ چرا؟", key: "جلگه های شمالی و غربی، به دلیل بارش کافی و پوشش گیاهی." },
    { grade: 7, lesson: 14, type: "essay", q: "چه مناطقی از کشور و به چه علت برای کشاورزی مناسب نیست؟", key: "نواحی مرکزی و کویری، به دلیل خشکی، شوری خاک و کمبود آب." },
    { grade: 7, lesson: 14, type: "essay", q: "چرا در مناطق مرکزی ایران گیاخاک (هوموس) خاک بسیار کم است؟", key: "به دلیل کم بودن پوشش گیاهی و بارش کم." },
    { grade: 7, lesson: 14, type: "testi", q: "در کدام مناطق ایران هوموس خاک کم است؟", options: ["مناطق جلگه ای", "مناطق کوهپایه ای", "مرکزی، شرقی و جنوبی", "همه موارد"], answer: [2] },
    { grade: 7, lesson: 14, type: "truefalse", q: "برای آنکه یک سانتی متر خاک زراعی تشکیل شود صدها سال وقت لازم است.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 14, type: "essay", q: "چه عواملی موجب از بین رفتن خاک می شود؟", key: "فرسایش آبی و بادی، شوری خاک، آلودگی، ساخت و ساز." },
    { grade: 7, lesson: 14, type: "essay", q: "کدام سازمان در کشور ما وظیفه حفاظت از خاک را بر عهده دارد؟", key: "سازمان حفاظت محیط زیست و وزارت جهاد کشاورزی." },
    { grade: 7, lesson: 15, type: "essay", q: "گردشگر به چه کسی گفته می شود؟", key: "کسی که برای تفریح، استراحت یا کار به جایی غیر از محل زندگی خود سفر می کند." },
    { grade: 7, lesson: 15, type: "essay", q: "زائر به چه کسی گفته می شود؟", key: "کسی که برای زیارت مکان های مذهبی سفر می کند." },
    { grade: 7, lesson: 15, type: "essay", q: "گردشگری در گذشته و حال را با یکدیگر مقایسه کنید.", key: "در گذشته سخت و کند بود و بیشتر انگیزه زیارتی داشت، امروزه سریع و آسان است و انگیزه های تفریحی و علمی دارد." },
    { grade: 7, lesson: 15, type: "essay", q: "انواع گردشگری را نام ببرید.", key: "طبیعت گردی، زیارتی، فرهنگی-تاریخی، سلامت، تجاری." },
    { grade: 7, lesson: 15, type: "truefalse", q: "همه ی مردم از مسافرت هدف یکسانی دارند.", options: ["درست", "غلط"], answer: [1] },
    { grade: 7, lesson: 15, type: "essay", q: "اهمیت گردشگری را بنویسید.", key: "ایجاد اشتغال، کسب درآمد، آشنایی با فرهنگ ها." },
    { grade: 7, lesson: 15, type: "jakhali", q: "گردشگری نقش مهمی در افزایش ...... مردم یک منطقه دارد.", answer: ["درآمد", "اشتغال"] },
    { grade: 7, lesson: 15, type: "jakhali", q: "یکی از وسایل مهمی که باید برای گردشگری از آن استفاده کرد، ...... است.", answer: ["نقشه", "راهنما"] },
    { grade: 7, lesson: 15, type: "essay", q: "بر روی نقشه راه ها چه چیزهایی مشخص شده است؟", key: "جاده ها، مسیرها، فاصله ها، پمپ بنزین ها، رستوران ها." },
    { grade: 7, lesson: 15, type: "testi", q: "کدامیک از موارد زیر بر روی نقشه راه ها مشخص نشده است؟", options: ["پمپ بنزین ها", "رشته کوه ها", "رستوران ها", "تعمیرگاه ها"], answer: [1] },
    { grade: 7, lesson: 15, type: "essay", q: "مقیاس نقشه راه ها چه کاربردی دارد؟", key: "برای محاسبه فاصله بین مبدا و مقصد." },
    { grade: 7, lesson: 16, type: "jakhali", q: "در کشور ما، بخش عمده ای از سفرها جنبه ی ...... دارد.", answer: ["زیارتی", "مذهبی"] },
    { grade: 7, lesson: 16, type: "essay", q: "سفرهای زیارتی به چه منظوری انجام می شود؟", key: "برای زیارت مکان های مقدس و تقویت معنویت." },
    { grade: 7, lesson: 16, type: "essay", q: "در ایران مساجد از چه نظر مورد توجه گردشگران می باشند؟", key: "از نظر معماری اسلامی و تاریخی." },
    { grade: 7, lesson: 16, type: "essay", q: "مهمترین مساجدی که در کشورمان از نظر معماری مورد توجه گردشگران است کدامند؟", key: "مسجد جامع اصفهان، مسجد امام، مسجد شیخ لطف الله." },
    { grade: 7, lesson: 16, type: "jakhali", q: "مهمترین قطب زیارتی ایران، شهر ...... می باشد.", answer: ["مشهد", "مشهد مقدس"] },
    { grade: 7, lesson: 16, type: "jakhali", q: "طبق آمار سالیانه حدود ...... میلیون نفر به شهر مقدس مشهد وارد می شوند.", answer: ["۲۰", "بیست"] },
    { grade: 7, lesson: 16, type: "essay", q: "اهمیت حرم مطهر امام رضا (ع) و مجموعه آستان قدس رضوی از چه نظر است؟", key: "از نظر مذهبی، تاریخی و معماری." },
    { grade: 7, lesson: 16, type: "essay", q: "آرامگاه کدام شخصیت های بزرگ علمی مذهبی در صحن های مطهر امام رضا (ع) می باشند؟", key: "شیخ بهایی، خواجه نصیرالدین طوسی، علامه طباطبایی." },
    { grade: 7, lesson: 16, type: "essay", q: "مجموعه آستان قدس رضوی شامل چه بخش هایی است؟", key: "حرم، مساجد، صحن ها، موزه ها، کتابخانه." },
    { grade: 7, lesson: 16, type: "essay", q: "در مجموعه آستان قدس رضوی کدام موزه ها قرار دارند؟", key: "موزه قرآن، موزه فرش، موزه آثار باستانی." },
    { grade: 7, lesson: 16, type: "essay", q: "در موزه امام رضا (ع) چه آثاری نگهداری می شود؟", key: "قرآن های خطی، آثار هنری، هدایای نفیس." },
    { grade: 7, lesson: 16, type: "truefalse", q: "ایران به دلیل دارا بودن تاریخ طولانی، آثار و بناهای متعددی دارد.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 16, type: "essay", q: "آثار و بناهای تاریخی ایران شامل چه چیزهایی است؟", key: "کاخ ها، مساجد، پل ها، کاروانسراها، آرامگاه ها." },
    { grade: 7, lesson: 16, type: "essay", q: "طبیعت گردی چیست؟", key: "سفر به طبیعت برای لذت بردن از زیبایی های آن بدون آسیب رساندن." },
    { grade: 7, lesson: 16, type: "essay", q: "علت تنوع زیستگاه ها در ایران چیست؟", key: "تنوع آب و هوایی و جغرافیایی." },
    { grade: 7, lesson: 16, type: "essay", q: "وظایف راهنمای گردشگر را نام ببرید.", key: "ارائه اطلاعات درست، راهنمایی مسیرها، حفظ امنیت گردشگران." },
    { grade: 7, lesson: 16, type: "essay", q: "در پارک های ملی چه مواردی ممنوع است؟", key: "شکار، صید، روشن کردن آتش، تخریب طبیعت، رها کردن زباله." },
    { grade: 7, lesson: 17, type: "essay", q: "میراث یعنی چه؟", key: "چیزی که از گذشتگان به ما رسیده است." },
    { grade: 7, lesson: 17, type: "essay", q: "میراث فرهنگی چیست؟", key: "آثار مادی و معنوی به جا مانده از گذشتگان که نشان دهنده فرهنگ و تمدن است." },
    { grade: 7, lesson: 17, type: "jakhali", q: "بخشی از آثاری که از گذشتگان برای ما به جا مانده است، ...... است.", answer: ["میراث فرهنگی"] },
    { grade: 7, lesson: 17, type: "essay", q: "میراث فرهنگی شامل چه چیزهایی می شود؟", key: "میراث مادی (بناها، اشیا) و میراث معنوی (زبان، آداب و رسوم، اعتقادات)." },
    { grade: 7, lesson: 17, type: "testi", q: "کدام یک از گزینه های زیر میراث فرهنگی مادی است؟", options: ["زبان", "بناهای تاریخی", "آداب و رسوم", "اعتقادات"], answer: [1] },
    { grade: 7, lesson: 17, type: "essay", q: "علم تاریخ چیست؟", key: "علم بررسی رویدادهای گذشته انسان و علل و نتایج آن ها." },
    { grade: 7, lesson: 17, type: "essay", q: "آشنایی با گذشته به ما چه کمکی می کند؟", key: "درس گرفتن از گذشته، شناخت هویت، برنامه ریزی برای آینده." },
    { grade: 7, lesson: 17, type: "essay", q: "مورخ کیست؟", key: "کسی که رویدادهای گذشته را مطالعه و بررسی می کند." },
    { grade: 7, lesson: 17, type: "essay", q: "مورخان در مطالعات خود از چه منابعی استفاده می کنند؟", key: "منابع نوشتاری، آثار باستانی، نقل قول ها." },
    { grade: 7, lesson: 17, type: "jakhali", q: "مورخان در کار خود از یافته ها و نتایج مطالعات ...... نیز استفاده می کنند.", answer: ["باستان شناسان", "باستان شناسی"] },
    { grade: 7, lesson: 17, type: "essay", q: "مراحل کار باستان شناسان را به ترتیب بنویسید.", key: "۱. کاوش. ۲. ثبت و مستندسازی. ۳. مطالعه و تحلیل." },
    { grade: 7, lesson: 17, type: "essay", q: "برخی پرسش های مهم تاریخی که مورخان با آن کار خود را شروع می کنند، بنویسید.", key: "چه اتفاقی افتاد؟ چه زمانی؟ چرا؟ چه نتایجی داشت؟" },
    { grade: 7, lesson: 17, type: "essay", q: "موزه ها چگونه مکان هایی هستند؟", key: "مکان هایی برای نگهداری، نمایش و مطالعه آثار تاریخی و فرهنگی." },
    { grade: 7, lesson: 17, type: "essay", q: "کارکردهای موزه را بنویسید.", key: "حفظ آثار، آموزش، پژوهش، جذب گردشگر." },
    { grade: 7, lesson: 17, type: "essay", q: "یکی از اهداف مهم وزارت میراث فرهنگی، گردشگری و صنایع دستی چیست؟", key: "حفاظت از آثار تاریخی و توسعه گردشگری." },
    { grade: 7, lesson: 17, type: "essay", q: "وزارت میراث فرهنگی، گردشگری و صنایع دستی چه فعالیت هایی انجام می دهد؟", key: "مرمت بناهای تاریخی، ثبت آثار ملی، حمایت از صنایع دستی." },
    { grade: 7, lesson: 17, type: "essay", q: "ما چگونه می توانیم به وزارت میراث فرهنگی، گردشگری و صنایع دستی کمک کنیم؟", key: "بازدید از موزه ها، حفظ آثار، معرفی جاذبه ها، نریختن زباله در مکان های تاریخی." },
    { grade: 7, lesson: 18, type: "essay", q: "در موزه ایران باستان چه آثاری نگهداری می شود؟", key: "آثار مربوط به دوران پیش از اسلام و دوران اولیه تاریخ ایران." },
    { grade: 7, lesson: 18, type: "essay", q: "علت نامگذاری موزه ایران باستان چیست؟", key: "چون آثار مربوط به ایران قبل از اسلام را در خود جای داده است." },
    { grade: 7, lesson: 18, type: "essay", q: "به چه علت تاریخ ایران را به دو دوره تقسیم کرده اند؟", key: "به دلیل ورود اسلام به ایران. (پیش از اسلام و پس از اسلام)" },
    { grade: 7, lesson: 18, type: "essay", q: "تاریخ ایران به دو دوره زمانی تقسیم شده است، آنها را توضیح دهید.", key: "دوره پیش از اسلام (از آریایی ها تا ساسانیان) و دوره پس از اسلام (از ورود اسلام تاکنون)." },
    { grade: 7, lesson: 18, type: "essay", q: "با توجه به مطالعات باستان شناسان، زندگی بشر چه مراحلی را طی کرده است؟", key: "دوره گردآوری غذا، دوره کشاورزی و یکجانشینی، دوره شهرنشینی." },
    { grade: 7, lesson: 18, type: "essay", q: "اولین روستاها چگونه بوجود آمدند؟", key: "با کشف کشاورزی، انسان ها در کنار زمین های کشاورزی ساکن شدند." },
    { grade: 7, lesson: 18, type: "essay", q: "چرا همه مردم روستا مجبور نبودند کار کشاورزی کنند؟", key: "به دلیل تولید مازاد غذا، برخی به مشاغل دیگر مانند صنعتگری پرداختند." },
    { grade: 7, lesson: 18, type: "essay", q: "چرا انسان ها خط را اختراع کردند؟", key: "برای ثبت اطلاعات، معاملات و انتقال پیام." },
    { grade: 7, lesson: 18, type: "essay", q: "نخستین تمدن های بشری چگونه به وجود آمدند؟", key: "با شکل گیری شهرها، حکومت ها و قوانین در کنار رودخانه ها." },
    { grade: 7, lesson: 18, type: "essay", q: "ویژگی های تمدن را نام ببرید.", key: "شهرنشینی، حکومت، خط، قوانین، تخصص مشاغل." },
    { grade: 7, lesson: 18, type: "essay", q: "در مورد شهر سوخته به سؤالات زیر پاسخ دهید. الف) در کجا قرار داشت؟ ب) چگونه تمدنی بود؟ ج) علت نامگذاری آن چیست؟", key: "الف) سیستان و بلوچستان. ب) تمدنی پیشرفته. ج) به دلیل آتش سوزی چند باره." },
    { grade: 7, lesson: 18, type: "essay", q: "آثار باقی مانده از تمدن ایلام چگونه کشف شد؟", key: "از طریق کاوش های باستان شناسی در خوزستان." },
    { grade: 7, lesson: 18, type: "jakhali", q: "مهمترین اثر به جا مانده از تمدن ایلام ...... است.", answer: ["زیگورات چغازنبیل", "چغازنبیل"] },
    { grade: 7, lesson: 18, type: "essay", q: "در مورد تمدن ایلامی ها توضیح دهید.", key: "تمدن کهنی در جنوب غربی ایران (خوزستان) که دارای خط و معماری بودند." },
    { grade: 7, lesson: 18, type: "jakhali", q: "تمدن جیرفت در نزدیکی ...... و در کنار رود ...... شناسایی شده است.", answer: ["کرمان", "هلیل رود"] },
    { grade: 7, lesson: 18, type: "essay", q: "سه تمدن که در گذشته های دور پدید آمدند و سپس از بین رفتند را نام ببرید؟", key: "شهر سوخته، ایلام، جیرفت." },
    { grade: 7, lesson: 18, type: "jakhali", q: "سرزمین های بین رود دجله و فرات را ...... می نامند.", answer: ["بین النهرین", "میان رودان"] },
    { grade: 7, lesson: 18, type: "essay", q: "در منطقه بین النهرین و کنار رود نیل کدام تمدن ها وجود داشتند؟", key: "تمدن های سومر، بابل، مصر." },
    { grade: 7, lesson: 18, type: "essay", q: "زندگی و روابط اجتماعی فرمانروایان در تمدن های قدیم چگونه بود؟", key: "فرمانروایان قدرت مطلق داشتند و مردم از آن ها اطاعت می کردند." },
    { grade: 7, lesson: 18, type: "jakhali", q: "حضرت نوح (ع) و حضرت ابراهیم (ع) در ...... می زیستند.", answer: ["بین النهرین", "بابل"] },
    { grade: 7, lesson: 18, type: "jakhali", q: "حضرت یوسف (ع) و حضرت موسی (ع) نیز مدت زیادی در ...... به سر بردند.", answer: ["مصر"] },
    { grade: 7, lesson: 18, type: "essay", q: "پیامبران از جانب خداوند چه مأموریتی داشتند؟", key: "هدایت انسان ها به سوی خداپرستی و اخلاق نیکو." },
    { grade: 7, lesson: 19, type: "essay", q: "آریایی ها چگونه مردمی بودند و در کجا ساکن شدند؟", key: "مردمی کوچ نشین و دامدار بودند که در فلات ایران ساکن شدند." },
    { grade: 7, lesson: 19, type: "essay", q: "سه قوم بزرگ آریایی را نام ببرید؟", key: "مادها، پارس ها، پارت ها." },
    { grade: 7, lesson: 19, type: "essay", q: "قبایل ماد در کجا زندگی می کردند؟", key: "در غرب ایران و نواحی همدان." },
    { grade: 7, lesson: 19, type: "essay", q: "علت ضعیف بودن مادها چه بودند؟", key: "پراکندگی قبایل و نداشتن حکومت واحد." },
    { grade: 7, lesson: 19, type: "testi", q: "کدام حکومت هر چند وقت یکبار به مادها حمله می کردند و اموالشان را به غارت می بردند؟", options: ["بابلی ها", "آشوری ها", "ایلامی ها", "سومری ها"], answer: [1] },
    { grade: 7, lesson: 19, type: "essay", q: "ذهیوک که بود و چگونه به عنوان فرمانروا انتخاب شد؟", key: "رهبر یکی از قبایل ماد بود که با اتحاد قبایل به پادشاهی رسید." },
    { grade: 7, lesson: 19, type: "jakhali", q: "اولین حکومت قدرتمند ایرانی به دست ...... پایه گذاری شد.", answer: ["مادها", "ذهیوک"] },
    { grade: 7, lesson: 19, type: "essay", q: "موسس سلسله مادها چه کسی بود؟", key: "ذهیوک (دیاکو)." },
    { grade: 7, lesson: 19, type: "jakhali", q: "رئیس یکی از قبایل مهم پارس، فردی به نام ...... بود.", answer: ["هخامنش"] },
    { grade: 7, lesson: 19, type: "testi", q: "بنیان گذار سلسله هخامنشیان چه کسی بود؟", options: ["کوروش", "ذهیوک", "هخامنش", "سلوکوس"], answer: [2] },
    { grade: 7, lesson: 19, type: "essay", q: "کوروش چگونه به پادشاهی رسید؟", key: "با شکست دادن پدربزرگش آستیاگ (پادشاه ماد)." },
    { grade: 7, lesson: 19, type: "essay", q: "کوروش چگونه توانست قلمرو ایران را گسترش دهد؟", key: "با لشکرکشی های موفق و رفتار نیکو با ملت های مغلوب." },
    { grade: 7, lesson: 19, type: "jakhali", q: "معروف ترین پادشاه هخامنشیان بعد از کوروش ...... بود.", answer: ["داریوش", "داریوش بزرگ"] },
    { grade: 7, lesson: 19, type: "essay", q: "چرا از حکومت هخامنشیان می توان به عنوان نخستین امپراتوری جهان نام برد؟", key: "چون توانستند سرزمین های بسیار وسیعی با اقوام و فرهنگ های مختلف را زیر یک حکومت واحد متحد کنند." },
    { grade: 7, lesson: 19, type: "testi", q: "در زمان هخامنشیان بین ایران و کدام کشور جنگ های متعددی روی داد؟", options: ["یونان", "روم", "آشوری ها", "اعراب"], answer: [0] },
    { grade: 7, lesson: 19, type: "essay", q: "بهانه حمله اسکندر مقدونی به ایران چه بود؟", key: "انتقام گرفتن از ایرانیان به خاطر حمله به یونان." },
    { grade: 7, lesson: 19, type: "essay", q: "اسکندر کدام سرزمین ها را تصرف کرد و عاقبت او چه شد؟", key: "تمام امپراتوری هخامنشی را تصرف کرد و در جوانی بیمار شد و مرد." },
    { grade: 7, lesson: 19, type: "essay", q: "سلسله سلوكيان را چه كسي تاسيس كرد؟", key: "سلوکوس (یکی از سرداران اسکندر)." },
    { grade: 7, lesson: 19, type: "essay", q: "سلسله اشکانیان را چه کسی تاسیس کرد؟", key: "ارشک." },
    { grade: 7, lesson: 19, type: "essay", q: "در زمان فرمانروایی چه کسی حکومت اشکانیان به امپراتوری قدرتمند تبدیل شد؟", key: "مهرداد دوم." },
    { grade: 7, lesson: 19, type: "jakhali", q: "آخرین حکومت پیش از ورود اسلام به ایران سلسله ...... بود.", answer: ["ساسانیان"] },
    { grade: 7, lesson: 19, type: "essay", q: "مؤسس سلسله ساسانیان چه کسی بود؟", key: "اردشیر بابکان." },
    { grade: 7, lesson: 19, type: "jakhali", q: "یکی از مهمترین پادشاهان ساسانی ...... است.", answer: ["خسرو انوشیروان", "شاپور اول", "انوشیروان"] },
    { grade: 7, lesson: 19, type: "essay", q: "اقدامات شاپور اول را بنویسید.", key: "شکست رومیان، اسارت امپراتور روم، توسعه شهرها." },
    { grade: 7, lesson: 19, type: "essay", q: "سرانجام سلسله ساسانی چگونه به پایان رسید؟", key: "با حمله اعراب مسلمان و شکست در جنگ نهاوند." },
    { grade: 7, lesson: 19, type: "essay", q: "آخرین پادشاه ساسانی که بود؟ و توسط چه کسی به قتل رسید؟", key: "یزدگرد سوم، توسط ماهوی سوری." },
    { grade: 7, lesson: 19, type: "essay", q: "مبدأ تاريخ هجري چيست؟", key: "هجرت پیامبر اسلام از مکه به مدینه." },
    { grade: 7, lesson: 19, type: "essay", q: "مورخان برای تعیین زمان رویدادهای قبل از اسلام از چه تقویمی استفاده می کنند؟", key: "از تقویم میلادی." },
    { grade: 7, lesson: 19, type: "jakhali", q: "مبدأ تقويم ميلادي تولد ...... است و نشانه اختصاري ...... است.", answer: ["حضرت مسیح", "م"] },
    { grade: 7, lesson: 19, type: "essay", q: "برای تعیین زمان رویدادهای قبل از میلاد حضرت مسیح (ع) از چه تقویمی استفاده می شود؟", key: "از تقویم قبل از میلاد (ق.م) استفاده می شود." },
    { grade: 7, lesson: 20, type: "jakhali", q: "در ایران باستان شیوه حکومت ...... بود.", answer: ["پادشاهی", "استبدادی", "مطلقه"] },
    { grade: 7, lesson: 20, type: "essay", q: "شیوه حکومت در ایران باستان را توضیح دهید.", key: "حکومت موروثی و مطلقه بود که شاه در راس آن قرار داشت." },
    { grade: 7, lesson: 20, type: "essay", q: "شاهان ایران باستان خود را چگونه افرادی می دانستند؟", key: "برگزیده خداوند و دارای فرّه ایزدی." },
    { grade: 7, lesson: 20, type: "essay", q: "در چه زمانی و چه کسانی می توانستند شاه را عزل یا برکنار کنند؟", key: "به جز در موارد نادر و با شورش، کسی نمی توانست شاه را برکنار کند." },
    { grade: 7, lesson: 20, type: "essay", q: "شاهان بر چه اموری فرمانروایی مطلق داشتند؟", key: "بر جان، مال و تمام امور کشور." },
    { grade: 7, lesson: 20, type: "essay", q: "زندگی شاهان ایران باستان چگونه بود؟", key: "در کاخ های مجلل، با تجملات زیاد و دور از مردم." },
    { grade: 7, lesson: 20, type: "jakhali", q: "هزینه زندگی شاهان ایران باستان از گرفتن ...... از مردم تأمین می شد.", answer: ["مالیات"] },
    { grade: 7, lesson: 20, type: "jakhali", q: "نخستین کسانی که سرزمین خود را به بخش های مختلف تقسیم کردند ...... بودند.", answer: ["مادها"] },
    { grade: 7, lesson: 20, type: "essay", q: "داریوش برای اداره بهتر کشور، آن را به چند قسمت تقسیم کرده بود و به هر قسمت چه می گفتند؟", key: "به ۲۰ ساتراپی (استان) تقسیم کرد و برای هر کدام یک ساتراپ (فرماندار) تعیین کرد." },
    { grade: 7, lesson: 20, type: "essay", q: "پایتخت های ایران باستان معمولا دارای چه ویژگی هایی بودند؟", key: "مرکز حکومت، دارای کاخ ها و معابد، محل تجمع ثروت و قدرت." },
    { grade: 7, lesson: 20, type: "essay", q: "پایتخت حکومت ها در ایران باستان را ذکر کنید.", key: "مادها: هگمتانه، هخامنشیان: پاسارگاد و تخت جمشید، اشکانیان: صددروازه، ساسانیان: تیسفون." },
    { grade: 7, lesson: 20, type: "essay", q: "چرا حکومت های ایران باستان دارای سپاه و نیروی نظامی مجهز بودند؟", key: "برای حفظ امنیت، سرکوب شورش ها و دفاع در برابر دشمنان." },
    { grade: 7, lesson: 20, type: "essay", q: "اشکانیان در تاریخ به چیزی مشهور بودند و در چه کارهایی مهارت داشتند؟", key: "به سوارکاران ماهر و تیراندازی سواره مشهور بودند." },
    { grade: 7, lesson: 20, type: "jakhali", q: "یکی از ابتکارات بزرگ داریوش هخامنشی علاوه بر سپاه معمولی، تشکیل ...... بود.", answer: ["سپاه جاویدان"] },
    { grade: 7, lesson: 20, type: "essay", q: "یکی از ابتکارات بزرگ داریوش هخامنشی تشکیل سپاه جاویدان بود، آن را توضیح دهید.", key: "نیرویی دائمی و آموزش دیده که همیشه آماده دفاع از کشور بودند." },
    { grade: 7, lesson: 20, type: "truefalse", q: "خدمت در سپاه جاویدان، بزرگترین آرزوی جوانان پارسی بود.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 21, type: "jakhali", q: "در ایران باستان ...... هسته اولیه جامعه را تشکیل می داد.", answer: ["خانواده"] },
    { grade: 7, lesson: 21, type: "essay", q: "ازدواج در نزد ایرانیان باستان چگونه بود؟", key: "ازدواج امری مقدس بود و بر اساس آیین و تشریفات انجام می شد." },
    { grade: 7, lesson: 21, type: "truefalse", q: "در ایران باستان پدر به عنوان سرپرست خانواده محسوب می شد.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 21, type: "essay", q: "در ایران باستان پدر چه وظایفی بر عهده داشت؟", key: "سرپرستی خانواده، تامین معاش، آموزش فرزندان." },
    { grade: 7, lesson: 21, type: "jakhali", q: "ایرانیان باستان برای اولاد ...... ارزش خاصی قائل بودند.", answer: ["پسر", "پسران"] },
    { grade: 7, lesson: 21, type: "essay", q: "خانواده ها در ایران باستان بیشتر مواد مورد نیاز خود را چگونه تأمین می کردند؟", key: "از طریق کشاورزی، دامداری و صنایع دستی." },
    { grade: 7, lesson: 21, type: "essay", q: "خانواده ها در ایران باستان چگونه مرکزی بودند؟ چه اصولی را به اعضای خود می آموختند؟", key: "محور زندگی اجتماعی بودند و اصول اخلاقی و دینی را به فرزندان می آموختند." },
    { grade: 7, lesson: 21, type: "essay", q: "در دوره ایران باستان بیشتر مردم در روستاها زندگی می کردند یا در شهرها؟ و چه شغلی داشتند؟", key: "در روستاها زندگی می کردند و شغل بیشتر آن ها کشاورزی و دامداری بود." },
    { grade: 7, lesson: 21, type: "essay", q: "در ایران باستان شهرها بیشتر محل زندگی چه کسانی بود؟", key: "حاکمان، درباریان، بازرگانان و صنعتگران." },
    { grade: 7, lesson: 21, type: "jakhali", q: "بی عدالتی و اختلافات طبقاتی در دوره ...... به اوج خود رسید.", answer: ["ساسانیان"] },
    { grade: 7, lesson: 21, type: "essay", q: "جامعه ساسانی به چند طبقه تقسیم می شدند؟ آن ها را نام ببرید.", key: "به چهار طبقه: ۱. اشراف و بزرگان ۲. روحانیون ۳. جنگاوران ۴. عامه مردم (کشاورزان و پیشه وران)." },
    { grade: 7, lesson: 21, type: "essay", q: "در جامعه ساسانی طبقه بزرگان شامل چه کسانی می شدند؟", key: "شاهزادگان، صاحبان زمین های بزرگ، مقامات عالی رتبه." },
    { grade: 7, lesson: 21, type: "essay", q: "در جامعه ساسانی عامه مردم شامل چه کسانی بودند؟", key: "کشاورزان، صنعتگران و بازرگانان." },
    { grade: 7, lesson: 21, type: "essay", q: "در جامعه ساسانی طبقه اشراف و بزرگان از چه امتیازاتی برخوردار بودند؟", key: "معافیت از مالیات، داشتن بهترین زمین ها، دسترسی به مناصب عالی." },
    { grade: 7, lesson: 21, type: "essay", q: "کشاورزان در دوره ساسانی از کدام حقوق اجتماعی محروم بودند؟", key: "از حقوق اجتماعی و سیاسی محروم بودند و به عنوان شهروند درجه دو شناخته می شدند." },
    { grade: 7, lesson: 21, type: "essay", q: "جامعۀ طبقاتی در دوره ساسانی چه ویژگی هایی داشت؟", key: "عدم تحرک اجتماعی، فاصله زیاد بین طبقات، ظلم به طبقات پایین." },
    { grade: 7, lesson: 21, type: "essay", q: "به نوشته هرودت ایرانیان دوره باستان چه ویژگی هایی داشتند؟", key: "آن ها را مردمی شجاع، راستگو، آزاده و میانه رو در خوردن و نوشیدن توصیف کرده است." },
    { grade: 7, lesson: 21, type: "essay", q: "شاهان و شاهزادگان در دوره ایران باستان چگونه زندگی می کردند؟ با ذکر مثال", key: "در کاخ های مجلل با بهترین امکانات، دور از مردم عادی." },
    { grade: 7, lesson: 22, type: "essay", q: "پژوهشگران معتقدند در کدام سرزمین برای اولین بار کشاورزی و دامپروری آغاز شده است؟", key: "در بین النهرین و فلات ایران." },
    { grade: 7, lesson: 22, type: "jakhali", q: "مهمترین پیشه و وسیلهٔ معیشت در ایران باستان ...... بود.", answer: ["کشاورزی"] },
    { grade: 7, lesson: 22, type: "essay", q: "در ایران باستان کشاورزی چه جایگاهی داشت؟", key: "شغل اصلی مردم و بسیار مورد احترام بود." },
    { grade: 7, lesson: 22, type: "essay", q: "مهمترین محصول زراعی ایران باستان چه بود؟", key: "گندم." },
    { grade: 7, lesson: 22, type: "essay", q: "ایرانیان باستان در کدام صنایع فعالیت داشتند؟", key: "فلزکاری، سفالگری، نساجی، قالی بافی." },
    { grade: 7, lesson: 22, type: "jakhali", q: "به فرمان داریوش اول هخامنشی، جاده ...... ساخته شد.", answer: ["شاهی", "ابریشم"] },
    { grade: 7, lesson: 22, type: "essay", q: "چه عواملی سبب رونق تجارت در دوره ایران باستان شد؟", key: "امنیت راه ها، وجود پول (سکه)، ساخت جاده ها." },
    { grade: 7, lesson: 22, type: "essay", q: "جاده ابریشم چه راهی بود؟", key: "راهی تجاری که چین را به اروپا متصل می کرد و از ایران می گذشت." },
    { grade: 7, lesson: 22, type: "testi", q: "پرسودترین و ارزشمندترین کالای تجاری در ایران باستان چه بود؟", options: ["گندم", "ابریشم", "برنج", "ذرت"], answer: [1] },
    { grade: 7, lesson: 22, type: "essay", q: "چرا حکومت های ایران باستان به خصوص ساسانیان مانع ارتباط مستقیم تجاری میان چین با روم اروپا می شدند؟", key: "برای در دست گرفتن تجارت و کسب درآمد بیشتر." },
    { grade: 7, lesson: 22, type: "essay", q: "ایران در دوره باستان صادر کننده چه کالاهایی بود؟", key: "ابریشم، فرش، ظروف فلزی، سنگ های قیمتی." },
    { grade: 7, lesson: 22, type: "jakhali", q: "در زمان هخامنشیان برای اولین بار به فرمان ...... سکه ای زرین به نام ...... ضرب شد.", answer: ["داریوش", "دریک"] },
    { grade: 7, lesson: 22, type: "essay", q: "تا قبل از ضرب سکه افراد کالاهای خود را چگونه می فروختند؟", key: "از طریق مبادله کالا با کالا (تهاتر)." },
    { grade: 7, lesson: 22, type: "essay", q: "در ایران باستان منبع اصلی درآمد حکومت ها از چه چیزی بود؟", key: "مالیات، غنایم جنگی، تجارت." },
    { grade: 7, lesson: 22, type: "essay", q: "در ایران باستان مالیات توسط چه کسانی پرداخت می شد؟", key: "توسط کشاورزان، صنعتگران و بازرگانان." },
    { grade: 7, lesson: 22, type: "essay", q: "مالیات سرانه در ایران باستان چه نوع مالیاتی بود؟", key: "مالیاتی که از هر نفر (فرد) دریافت می شد." },
    { grade: 7, lesson: 22, type: "essay", q: "مأموران مالیاتی در ایران باستان با مردم چه رفتاری داشتند؟", key: "اغلب با ظلم و ستم و زورگویی با مردم رفتار می کردند." },
    { grade: 7, lesson: 22, type: "essay", q: "درآمدهای حکومتی در ایران باستان صرف چه کارهایی می شد؟", key: "هزینه های دربار، ساخت کاخ ها، تجهیز سپاه، ساخت جاده ها." },
    { grade: 7, lesson: 23, type: "truefalse", q: "در ایران باستان، تعلیمات مذهبی نقش و تأثیر زیادی در زندگی فردی و اجتماعی داشت.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 23, type: "essay", q: "اقوام آریایی کدام عناصر خلقت را مقدس می دانستند؟", key: "آتش، آب، خاک، باد." },
    { grade: 7, lesson: 23, type: "essay", q: "پیامبر ایران باستان چه نام داشت و در چه زمانی می زیست؟", key: "زرتشت، حدود ۳۷۰۰ سال پیش." },
    { grade: 7, lesson: 23, type: "essay", q: "در آیین زرتشت، اهورا مزدا و اهریمن منشأ چه چیزهایی بود؟", key: "اهورا مزدا منشأ خوبی ها و اهریمن منشأ بدی ها بود." },
    { grade: 7, lesson: 23, type: "essay", q: "زرتشت پیروان خود را به چه چیزهایی سفارش می کرد؟", key: "به راستگویی، نیکوکاری، پرهیز از دروغ و ظلم." },
    { grade: 7, lesson: 23, type: "jakhali", q: "پس از مرگ زرتشت پیروانش تعالیم او را در کتابی به نام ...... گردآوری کردند.", answer: ["اوستا"] },
    { grade: 7, lesson: 23, type: "truefalse", q: "ایرانیان باستان آتش را مقدس می شمردند.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 23, type: "essay", q: "در دوره ساسانی چه دین هایی رواج داشت؟", key: "زرتشتی، مسیحیت، یهودیت، مانوی." },
    { grade: 7, lesson: 23, type: "jakhali", q: "در دوره ساسانیان دین ...... دین رسمی کشور اعلام شد.", answer: ["زرتشتی"] },
    { grade: 7, lesson: 23, type: "jakhali", q: "غذای اصلی مردم ایران باستان غلات مخصوصا ...... و ...... بود.", answer: ["گندم", "جو"] },
    { grade: 7, lesson: 23, type: "essay", q: "غذای ایرانیان باستان چه بود؟", key: "غلات (نان)، گوشت، میوه، سبزیجات، لبنیات." },
    { grade: 7, lesson: 23, type: "essay", q: "آداب غذا خوردن در نزد ایرانیان باستان چگونه بود؟", key: "با نظم، شستن دست ها، پرهیز از پرخوری." },
    { grade: 7, lesson: 23, type: "truefalse", q: "ایرانیان باستان برای آرد کردن غلات، آسیاب های آبی را ابداع کرده بودند.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 23, type: "jakhali", q: "نخستین کسانی که شلوار را طراحی کردند و پوشیدند ...... بودند.", answer: ["ایرانیان", "مادها"] },
    { grade: 7, lesson: 23, type: "essay", q: "پوشاک اصلی مردم ایران باستان چه بود؟", key: "پیراهن، شلوار، کفش، کلاه." },
    { grade: 7, lesson: 23, type: "essay", q: "از دیرباز مردم ایران به کدام ورزش ها علاقه داشتند؟", key: "چوگان، تیراندازی، کشتی." },
    { grade: 7, lesson: 23, type: "essay", q: "از نظر هرودوت ایرانیان به فرزندان خود چه چیزهایی را می آموختند؟", key: "سوارکاری، تیراندازی و راستگویی." },
    { grade: 7, lesson: 23, type: "essay", q: "کدام ورزش ها مورد علاقه ایرانیان باستان بود و در آن دوره رواج داشت؟", key: "چوگان، تیراندازی، کشتی، شکار." },
    { grade: 7, lesson: 23, type: "testi", q: "چوگان بازی ابداع چه کسانی بود؟", options: ["ایرانیان", "رومیان", "یونانیان", "هندیان"], answer: [0] },
    { grade: 7, lesson: 23, type: "essay", q: "معنی واژه جشن چیست؟", key: "شادمانی و سرور." },
    { grade: 7, lesson: 23, type: "truefalse", q: "بیشتر جشن های دوره ایران باستان اهمیت دینی داشته است.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 23, type: "essay", q: "مهمترین جشن های دوره ایران باستان را نام ببرید.", key: "نوروز، مهرگان، سده، تیرگان." },
    { grade: 7, lesson: 23, type: "truefalse", q: "یکی از بزرگترین و باشکوه ترین جشن های ایران باستان جشن نوروز بود.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 23, type: "essay", q: "در نزد ایرانیان باستان نوروز پیام آور چیست؟", key: "پیام آور نو شدن طبیعت و شادمانی." },
    { grade: 7, lesson: 23, type: "essay", q: "در مورد زمان پیدایش نوروز توضیح دهید.", key: "پیدایش آن به زمان جمشید (پادشاه اساطیری) نسبت داده شده است." },
    { grade: 7, lesson: 23, type: "jakhali", q: "در زمان هخامنشیان جشن نوروز در ...... برگزار می شد.", answer: ["تخت جمشید", "پاسارگاد"] },
    { grade: 7, lesson: 23, type: "essay", q: "آیین نوروز در عهد باستان چگونه بود؟", key: "برگزاری مراسم در کاخ شاهی، دادن هدایا به شاه، چیدن سفره هفت سین." },
    { grade: 7, lesson: 23, type: "truefalse", q: "در ایام نوروز از شلوغ ترین مکان های ایران می توان حرم امام رضا(ع) را نام برد.", options: ["درست", "غلط"], answer: [0] },
    { grade: 7, lesson: 23, type: "truefalse", q: "نوروز را فقط در ایران جشن می گیرند و مراسم مخصوص به خود دارند.", options: ["درست", "غلط"], answer: [1] },
    { grade: 7, lesson: 24, type: "essay", q: "اساس گسترش دانش هنر و معماری ایرانیان چه بود؟", key: "نیازهای اجتماعی و اعتقادات دینی." },
    { grade: 7, lesson: 24, type: "essay", q: "زبان فارسی از چه دوره ای در ایران باستان رایج بود؟", key: "از دوره هخامنشیان." },
    { grade: 7, lesson: 24, type: "essay", q: "زبان ایرانیان در دوره های زیر را بنویسید. (هخامنشیان، اشکانیان، ساسانیان)", key: "هخامنشیان: پارسی باستان، اشکانیان: پهلوی اشکانی، ساسانیان: پهلوی ساسانی." },
    { grade: 7, lesson: 24, type: "essay", q: "در زمان هخامنشیان خط ایرانیان چه بوده است؟", key: "خط میخی." },
    { grade: 7, lesson: 24, type: "essay", q: "کتیبه های بیستون و تخت جمشید به چه زبانی و با چه خطی نوشته شده است؟", key: "به زبان پارسی باستان و با خط میخی." },
    { grade: 7, lesson: 24, type: "essay", q: "در دوره اشکانیان و ساسانیان کدام خط رواج داشت؟", key: "خط پهلوی." },
    { grade: 7, lesson: 24, type: "essay", q: "چگونه پی می بریم ایرانیان در گذشته با علوم گوناگونی آشنا بودند؟", key: "از طریق مطالعه کتیبه ها، آثار باستانی و کتاب های به جا مانده." },
    { grade: 7, lesson: 24, type: "essay", q: "کدام نیاز ایرانیان باستان باعث اختراع تقویم شد؟", key: "نیاز به دانستن زمان کشاورزی و برگزاری مراسم مذهبی." },
    { grade: 7, lesson: 24, type: "essay", q: "تقویم خورشیدی شمسی ایرانیان باستان چگونه بود؟", key: "بر اساس گردش زمین به دور خورشید و حرکت خورشید در آسمان." },
    { grade: 7, lesson: 24, type: "essay", q: "در کتاب اوستا از چند نوع پزشک نام برده شده است؟ آن ها را نام ببرید.", key: "سه نوع: پزشک با دارو، پزشک با گیاهان، پزشک با جراحی." },
    { grade: 7, lesson: 24, type: "jakhali", q: "قدیمی ترین مدرسه پزشکی در دوره ...... تأسیس گردید.", answer: ["ساسانیان"] },
    { grade: 7, lesson: 24, type: "essay", q: "قدیمی ترین مدرسه پزشکی جهان چه نام داشت و توسط چه کسی تأسیس شده بود؟", key: "جندی شاپور، توسط شاپور اول." },
    { grade: 7, lesson: 24, type: "essay", q: "در مدرسه جندی شاپور کدام رشته ها تدریس می شد؟", key: "پزشکی، فلسفه، ریاضیات، نجوم." },
    { grade: 7, lesson: 24, type: "essay", q: "در عصر باستان، صنعتگران و هنرمندان در کدام رشته ها مهارت داشتند؟", key: "فلزکاری، سفالگری، نساجی، معماری." },
    { grade: 7, lesson: 24, type: "testi", q: "کدامیک از بناهای زیر از نظر معماری، وسعت و عظمت، شهرت جهانی دارد؟", options: ["تخت جمشید", "تخت سلیمان", "طاق بستان", "طاق کسری"], answer: [3] },
    { grade: 7, lesson: 24, type: "essay", q: "کدام بناها پیشرفت ایرانیان را در معماری نشان می دهد؟", key: "تخت جمشید، طاق کسری، گنبدها، پل ها." }
